function emdo_7693_category( string $kind ): WP_Term {
	$slug = 'ham' === $kind ? 'jamones-y-paletas' : 'aceites';
	$name = 'ham' === $kind ? 'Jamones y paletas' : 'Aceites';
	$term = get_category_by_slug( $slug );
	if ( ! $term instanceof WP_Term ) {
		$term = get_term_by( 'name', $name, 'category' );
	}
	if ( ! $term instanceof WP_Term ) {
		throw new RuntimeException( 'Missing production category: ' . $name );
	}

	$en_name = 'ham' === $kind ? 'Hams and shoulders' : 'Olive oil';
	$en_slug = 'ham' === $kind ? 'hams-and-shoulders' : 'olive-oil';
	if ( '' === (string) get_term_meta( $term->term_id, '_en_US_name', true ) ) {
		update_term_meta( $term->term_id, '_en_US_name', $en_name );
	}
	if ( '' === (string) get_term_meta( $term->term_id, '_en_US_slug', true ) ) {
		update_term_meta( $term->term_id, '_en_US_slug', $en_slug );
	}
	update_term_meta( $term->term_id, '_en_US_published', '1' );
	return $term;
}

