	if ( 'ham' === $kind ) {
		$out .= $is_es
			? '<p>Antes de comprar, comprueba la denominación de venta, la categoría del ibérico, el porcentaje racial cuando corresponda, el productor, el formato, el peso y las instrucciones de conservación. Si existe una DOP, verifica además su identificación específica. El objetivo no es acumular sellos, sino saber qué aporta cada dato y si encaja con lo que quieres comprar.</p>'
			: '<p>Before buying, check the sales designation, Iberian category, breed percentage where applicable, producer, format, weight and storage instructions. If a PDO is claimed, verify its specific identification as well. The goal is not to collect seals, but to understand what each piece of information contributes and whether it matches what you want to buy.</p>';
	} else {
		$out .= $is_es
			? '<p>Antes de comprar, comprueba que la categoría sea la que buscas, revisa origen y DOP si se declaran, variedad o coupage, campaña cuando esté disponible, tamaño del envase y la rapidez con la que lo vas a consumir. El precio por litro es útil, pero debe leerse junto con frescura, formato y uso previsto.</p>'
			: '<p>Before buying, confirm the oil category you want, check origin and PDO where claimed, variety or blend, harvest year when available, package size and how quickly you expect to use it. Price per litre is useful, but should be read together with freshness, format and intended use.</p>';
	}

	$out .= emdo_7693_faq( $a, $lang );

	$out .= $is_es ? '<h2>Guías relacionadas</h2>' : '<h2>Related guides</h2>';
	$out .= emdo_7693_internal_links( $kind, $lang );

	$out .= $is_es ? '<h2>Conclusión</h2>' : '<h2>Bottom line</h2>';
	if ( 'ham' === $kind ) {
		$out .= $is_es
			? '<p>La idea principal es usar el origen como información verificable, no como atajo. Cuanto mejor puedas relacionar territorio, certificación, categoría y elaboración, más fácil será comparar productos con criterios útiles y evitar pagar por términos que no significan exactamente lo que parecen.</p>'
			: '<p>The main idea is to use origin as verifiable information rather than a shortcut. The better you connect territory, certification, legal category and processing, the easier it becomes to compare products on useful criteria instead of paying for words that do not mean exactly what they appear to mean.</p>';
	} else {
		$out .= $is_es
			? '<p>La idea principal es leer el aceite como un conjunto: categoría, origen, variedad, campaña, perfil y conservación. Esa combinación permite elegir por gusto y uso real sin convertir una sola palabra de la etiqueta en un indicador absoluto de calidad.</p>'
			: '<p>The main idea is to read the oil as a whole: category, origin, variety, harvest, sensory profile and storage. That combination makes it easier to choose for taste and real use without turning one word on a label into an absolute quality score.</p>';
	}

	$out .= $is_es ? '<h2>Fuentes y referencias</h2><p>Para esta guía se han priorizado fuentes institucionales y organismos de las denominaciones. Los pliegos vigentes son la referencia cuando se necesita comprobar un requisito concreto.</p>' : '<h2>Sources and references</h2><p>This guide prioritises institutional sources and designation bodies. Current product specifications are the reference point when a specific certification requirement needs to be checked.</p>';
	$out .= '<ul>';
	foreach ( (array) $a['sources'] as $source ) {
		$host = wp_parse_url( (string) $source, PHP_URL_HOST );
		$out .= '<li><a href="' . esc_url( (string) $source ) . '" rel="noopener noreferrer">' . emdo_7693_e( (string) $host ) . '</a></li>';
	}
	$out .= '</ul>';

	return $out;
}

function emdo_7693_meta_title( string $title ): string {
	if ( function_exists( 'mb_strlen' ) && mb_strlen( $title, 'UTF-8' ) > 62 ) {
		return rtrim( mb_substr( $title, 0, 59, 'UTF-8' ) ) . '…';
	}
	return $title;
}

function emdo_7693_meta_description( string $excerpt ): string {
	if ( function_exists( 'mb_strlen' ) && mb_strlen( $excerpt, 'UTF-8' ) > 158 ) {
		return rtrim( mb_substr( $excerpt, 0, 155, 'UTF-8' ) ) . '…';
	}
	return $excerpt;
}

function emdo_7693_upsert( array $a, WP_Term $term, int $image_id ): int {
	$slug = (string) $a['slug'];
	$existing = get_page_by_path( $slug, OBJECT, 'post' );
	if ( $existing instanceof WP_Post ) {
		$marker = (string) get_post_meta( $existing->ID, '_emdo_editorial_batch_76_93', true );
		if ( EMDO_BATCH_76_93_MARKER !== $marker ) {
			throw new RuntimeException( 'Refusing to overwrite existing non-batch post: ' . $slug );
		}
	}

	$sample_ids = get_posts(
		array(
			'post_type'      => 'post',
			'post_status'    => 'publish',
			'posts_per_page' => 1,
			'fields'         => 'ids',
			'category__in'   => array( (int) $term->term_id ),
		)
	);
	$author = ! empty( $sample_ids ) ? (int) get_post_field( 'post_author', (int) $sample_ids[0] ) : 1;
	if ( $author <= 0 ) {
		$author = 1;
	}

	$postarr = array(
		'post_type'      => 'post',
		'post_status'    => 'publish',
		'post_title'     => (string) $a['title'],
		'post_name'      => $slug,
		'post_excerpt'   => (string) $a['excerpt'],
		'post_content'   => emdo_7693_render( $a, 'es' ),
		'post_author'    => $author,
		'post_category'  => array( (int) $term->term_id ),
		'comment_status' => 'closed',
		'ping_status'    => 'closed',
	);

	if ( $existing instanceof WP_Post ) {
		$postarr['ID'] = (int) $existing->ID;
		$result = wp_update_post( wp_slash( $postarr ), true );
	} else {
		$result = wp_insert_post( wp_slash( $postarr ), true );
	}
	if ( is_wp_error( $result ) || (int) $result <= 0 ) {
		$message = is_wp_error( $result ) ? $result->get_error_message() : 'unknown';
		throw new RuntimeException( 'Failed to publish ' . $slug . ': ' . $message );
	}

	$post_id = (int) $result;
	update_post_meta( $post_id, '_emdo_editorial_batch_76_93', EMDO_BATCH_76_93_MARKER );
	update_post_meta( $post_id, '_emdo_editorial_position', (string) (int) $a['pos'] );
	update_post_meta( $post_id, '_emdo_seo_title', emdo_7693_meta_title( (string) $a['title'] ) );
	update_post_meta( $post_id, '_emdo_seo_description', emdo_7693_meta_description( (string) $a['excerpt'] ) );
	update_post_meta( $post_id, '_en_US_post_title', (string) $a['en_title'] );
	update_post_meta( $post_id, '_en_US_post_name', (string) $a['en_slug'] );
	update_post_meta( $post_id, '_en_US_post_excerpt', (string) $a['en_excerpt'] );
	update_post_meta( $post_id, '_en_US_post_content', emdo_7693_render( $a, 'en' ) );
	update_post_meta( $post_id, '_en_US_seo_title', emdo_7693_meta_title( (string) $a['en_title'] ) );
	update_post_meta( $post_id, '_en_US_seo_description', emdo_7693_meta_description( (string) $a['en_excerpt'] ) );
	update_post_meta( $post_id, '_en_US_ready', '1' );
	update_post_meta( $post_id, '_en_US_published', '1' );

	if ( $image_id > 0 ) {
		set_post_thumbnail( $post_id, $image_id );
	}

	return $post_id;
}

$ham_term = emdo_7693_category( 'ham' );
$oil_term = emdo_7693_category( 'oil' );
$ham_image = emdo_7693_featured_image( 'ham', (int) $ham_term->term_id );
$oil_image = emdo_7693_featured_image( 'oil', (int) $oil_term->term_id );

$published = array();
foreach ( $articles as $article ) {
	$kind = (string) $article['cat'];
	$term = 'ham' === $kind ? $ham_term : $oil_term;
	$image_id = 'ham' === $kind ? $ham_image : $oil_image;
	$post_id = emdo_7693_upsert( $article, $term, $image_id );

	$es_words = str_word_count( wp_strip_all_tags( (string) get_post_field( 'post_content', $post_id ) ) );
	$en_words = str_word_count( wp_strip_all_tags( (string) get_post_meta( $post_id, '_en_US_post_content', true ) ) );
	$en_title = (string) get_post_meta( $post_id, '_en_US_post_title', true );
	$en_slug  = (string) get_post_meta( $post_id, '_en_US_post_name', true );
	$en_pub   = (string) get_post_meta( $post_id, '_en_US_published', true );

	if ( 'publish' !== get_post_status( $post_id ) || '' === $en_title || '' === $en_slug || '1' !== $en_pub ) {
		throw new RuntimeException( 'Verification failed for post ID ' . $post_id );
	}
	if ( $es_words < 500 || $en_words < 430 ) {
		throw new RuntimeException( 'Article too short after render: ' . $article['slug'] . ' ES=' . $es_words . ' EN=' . $en_words );
	}

	$published[] = array(
		'position' => (int) $article['pos'],
		'id'       => $post_id,
		'slug'     => (string) $article['slug'],
		'en_slug'  => $en_slug,
		'category' => $term->name,
		'es_words' => $es_words,
		'en_words' => $en_words,
		'image_id' => (int) get_post_thumbnail_id( $post_id ),
	);
}

echo "EMDO_EDITORIAL_76_93_BEGIN\n";
echo wp_json_encode(
	array(
		'marker'    => EMDO_BATCH_76_93_MARKER,
		'count'     => count( $published ),
		'ham_image' => $ham_image,
		'oil_image' => $oil_image,
		'posts'     => $published,
	),
	JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
) . "\n";
echo "EMDO_EDITORIAL_76_93_END\n";
